#!/usr/bin/env node
// Summarise Android lint XML reports for the android.yml lint job:
//   node .github/ci/android/lint-summary.mjs <lint-results-*.xml>...
// Writes a per-report severity table and the most frequent issue ids to
// $GITHUB_STEP_SUMMARY (stdout when unset), and emits a warning annotation
// for findings in tracked sources (app/modules, pce), capped so a noisy run
// cannot flood the PR. Reporting only: exits 0 unless no report could be read.
import { appendFileSync, existsSync, readFileSync } from 'node:fs';
import { dirname, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../../..');
const SEVERITIES = ['Fatal', 'Error', 'Warning', 'Information'];
const MAX_ANNOTATIONS = 30;

const files = process.argv.slice(2).filter((f) => existsSync(f));
if (!files.length) {
  console.error('lint-summary: no lint XML report found (did lint run?)');
  process.exit(1);
}

const reports = files.map((file) => ({ file, ...where(file), issues: parseLintXml(readFileSync(file, 'utf8')) }));
const all = reports.flatMap((r) => r.issues);

const lines = [
  '### Android lint',
  '',
  '| Module | Variant | Fatal | Error | Warning | Info |',
  '| --- | --- | ---: | ---: | ---: | ---: |',
  ...reports.map((r) => {
    const n = (s) => r.issues.filter((i) => i.severity === s).length;
    return `| ${r.module} | ${r.variant} | ${SEVERITIES.map(n).join(' | ')} |`;
  }),
  '',
];
const byId = new Map();
for (const i of all) {
  const row = byId.get(i.id) ?? { id: i.id, severity: i.severity, count: 0 };
  row.count += 1;
  byId.set(i.id, row);
}
const top = [...byId.values()].sort((a, b) => b.count - a.count).slice(0, 15);
if (top.length) {
  lines.push('| Top issue ids | Severity | Count |', '| --- | --- | ---: |');
  lines.push(...top.map((t) => `| \`${t.id}\` | ${t.severity} | ${t.count} |`), '');
}
lines.push('Reports (HTML, XML, SARIF) are in the `android-lint-reports` artifact.', '');
const text = `${lines.join('\n')}\n`;
if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, text);
else process.stdout.write(text);

// Annotations: only files in this repository's tracked trees. app/android is
// generated by prebuild and node_modules is third-party, so neither is ours
// to fix.
let annotated = 0;
const seen = new Set();
for (const i of all) {
  if (annotated >= MAX_ANNOTATIONS) break;
  const rel = i.file ? relative(ROOT, i.file) : '';
  if (!rel || rel.startsWith('..') || !/^(app\/modules|pce)\//.test(rel) || /(^|\/)(build|node_modules)\//.test(rel)) {
    continue;
  }
  const key = `${rel}:${i.line}:${i.id}`;
  if (seen.has(key)) continue; // the runner is linted once per flavor
  seen.add(key);
  const line = i.line ? `,line=${i.line}` : '';
  const title = escapeProperty(`Android lint ${i.id} (${i.severity})`);
  console.log(`::warning file=${escapeProperty(rel)}${line},title=${title}::${escape(i.message)}`);
  annotated += 1;
}
console.log(`lint-summary: ${all.length} issues in ${reports.length} reports, ${annotated} annotated`);

// lint-results-<variant>.xml under <module>/build/reports/.
function where(file) {
  const rel = relative(ROOT, resolve(file));
  const variant = rel.match(/lint-results-([^/]+)\.xml$/)?.[1] ?? '?';
  const module =
    rel.match(/^app\/modules\/([^/]+)\//)?.[1] ?? (rel.startsWith('app/android/app/') ? 'app' : rel.split('/build/')[0]);
  return { module, variant };
}

// Lint's XML: <issue id=".." severity=".." message=".." ...> with one or more
// <location file=".." line=".." column=".."/> children. The first location
// is the primary one.
function parseLintXml(xml) {
  const out = [];
  for (const m of xml.matchAll(/<issue\b([^>]*)>([\s\S]*?)<\/issue>|<issue\b([^>]*)\/>/g)) {
    const a = attrs(m[1] ?? m[3]);
    const loc = attrs((m[2] ?? '').match(/<location\b([^>]*)\/?>/)?.[1] ?? '');
    out.push({
      id: a.id ?? '?',
      severity: SEVERITIES.includes(a.severity) ? a.severity : a.severity === 'Ignore' ? 'Information' : 'Warning',
      message: a.message ?? '',
      file: loc.file,
      line: loc.line,
    });
  }
  return out;
}

function attrs(s) {
  const out = {};
  for (const m of s.matchAll(/([\w:-]+)="([^"]*)"/g)) out[m[1]] = decode(m[2]);
  return out;
}

function decode(s) {
  return s
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)))
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

// Workflow-command data escaping (%, CR, LF).
function escape(s) {
  return s.replace(/%/g, '%25').replace(/\r/g, '%0D').replace(/\n/g, '%0A');
}

function escapeProperty(s) {
  return escape(s).replace(/:/g, '%3A').replace(/,/g, '%2C');
}
